INSERT INTO "announcements" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at", "cover_image") VALUES (1, 'Informasi PPDB Tahun Ajaran Baru', 'informasi-ppdb-tahun-ajaran-baru', 'Formulir PPDB online telah tersedia melalui website resmi sekolah.', 'Calon wali murid dapat mengisi formulir PPDB online dan mengunggah dokumen dasar sesuai ketentuan. Setelah submit, simpan nomor pendaftaran yang muncul di halaman sukses.', 'draft', '2026-06-14 17:06:36', '2026-06-07 16:03:20', '2026-06-14 17:06:36', NULL);
INSERT INTO "announcements" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at", "cover_image") VALUES (2, 'Jadwal Pengambilan Seragam Siswa', 'jadwal-pengambilan-seragam-siswa', 'Pengambilan seragam dilakukan bertahap sesuai jadwal kelas.', 'Orang tua/wali dimohon membawa bukti administrasi saat pengambilan seragam. Informasi jadwal disampaikan melalui wali kelas dan kanal resmi madrasah.', 'published', '2026-06-13 17:06:36', '2026-06-07 16:03:20', '2026-06-14 17:06:36', NULL);
INSERT INTO "announcements" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at", "cover_image") VALUES (3, 'Libur Kegiatan Belajar Hari Besar Nasional', 'libur-kegiatan-belajar-hari-besar-nasional', 'Kegiatan belajar diliburkan sementara sesuai kalender pendidikan.', 'Seluruh siswa kembali mengikuti pembelajaran pada hari berikutnya sesuai jadwal reguler.', 'published', '2026-06-12 17:06:36', '2026-06-07 16:03:20', '2026-06-14 17:06:36', NULL);
INSERT INTO "announcements" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at", "cover_image") VALUES (4, 'TEST PENGUMUMAN', 'test-pengumuman', 'Lorem Ipsum is simply dummy text of the printing and typesetting industry.', '<p><img src="http://localhost/storage/jD9yy4mL3HgWozHOP4aWIkfAZLCuo5AqY4Ek89eD.webp" alt="lorem ipsum" data-id="jD9yy4mL3HgWozHOP4aWIkfAZLCuo5AqY4Ek89eD.webp"><strong><br><br>Lorem Ipsum</strong> is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry&#039;s standard dummy text ever since 1966, when designers at Letraset and James Mosley, the librarian at St Bride Printing Library, took a 1914 Cicero translation and scrambled it to make dummy text for Letraset&#039;s Body Type sheets. It has survived not only many decades, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised thanks to these sheets and more recently with desktop publishing software including versions of Lorem Ipsum.<br><br><img src="http://localhost/storage/NyuGbOiUMXRjbxdozHNa1JbwaxtUh21U83WBF6QB.jpg" alt="lorem jalan" data-id="NyuGbOiUMXRjbxdozHNa1JbwaxtUh21U83WBF6QB.jpg"><br></p>', 'draft', '2026-06-08 11:38:33', '2026-06-08 11:38:44', '2026-06-14 17:06:36', NULL);
INSERT INTO "announcements" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at", "cover_image") VALUES (5, 'Penerimaan Peserta Didik Baru Tahun Ajaran 2026/2027', 'ppdb-mi-hubbul-wathan-2026-2027', 'Pendaftaran peserta didik baru MI Hubbul Wathan Toli-Toli dibuka mulai 2 Juni 2026.', '<p>Pendaftaran peserta didik baru MI Hubbul Wathan Toli-Toli untuk tahun ajaran 2026/2027 dibuka mulai <strong>2 Juni 2026</strong>.</p>
