INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (1, 'Profil Sekolah', 'profil-sekolah', 'Mengenal MI Hubbul Wathan sebagai madrasah ibtidaiyah yang berorientasi pada akhlak, ilmu, dan kemandirian.', 'MI Hubbul Wathan adalah madrasah ibtidaiyah yang menyelenggarakan pendidikan dasar dengan suasana belajar tertib, religius, dan dekat dengan kebutuhan orang tua.
INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (2, 'Visi Misi', 'visi-misi', 'Visi dan misi resmi MI Hubbul Wathan.', '<img src="/storage/pages/visi-misi-mi-hubbul-wathan.jpg" alt="Visi dan misi MI Hubbul Wathan">
INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (3, 'Fasilitas', 'fasilitas', 'Sarana utama yang mendukung pembelajaran dan kegiatan siswa MI Hubbul Wathan.', '<p>MI Hubbul Wathan menyediakan fasilitas utama untuk mendukung pembelajaran, kesehatan, dan aktivitas peserta didik.</p>
INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (4, 'Kontak', 'kontak', 'Informasi kontak, media sosial, dan lokasi MI Hubbul Wathan.', '<p>Untuk informasi sekolah dan layanan administrasi, silakan hubungi MI Hubbul Wathan melalui kanal resmi berikut.</p><ul><li>WhatsApp: 085396590157</li><li>Email: <a href="mailto:yppm.hubbulwathan@gmail.com">yppm.hubbulwathan@gmail.com</a></li><li>Instagram: <a href="https://www.instagram.com/yppm.hubbulwathan" target="_blank" rel="noopener">@yppm.hubbulwathan</a></li><li>Facebook: <a href="https://www.facebook.com/yppm.hubbulwathan" target="_blank" rel="noopener">@yppm.hubbulwathan</a></li></ul>', 'published', '2026-06-14 17:06:36', '2026-06-07 16:03:19', '2026-06-14 17:06:36');
INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (5, 'Sambutan Kepala Madrasah', 'sambutan-kepala-madrasah', 'Pesan Kepala MI Hubbul Wathan untuk peserta didik, orang tua, dan masyarakat.', '<p>Assalamu''alaikum warahmatullahi wabarakatuh.</p>
INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (6, 'Sejarah Singkat', 'sejarah-singkat', 'Perjalanan MI Hubbul Wathan sebagai lembaga pendidikan dasar Islam di Kabupaten Konawe.', '<p>MI Hubbul Wathan hadir sebagai lembaga pendidikan dasar Islam di Kabupaten Konawe untuk mendukung kebutuhan pendidikan anak-anak di lingkungan sekitar.</p>
INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (7, 'Struktur Organisasi', 'struktur-organisasi', 'Susunan pimpinan, pengelola, guru, dan tenaga kependidikan MI Hubbul Wathan.', '<p>Struktur organisasi menampilkan pembagian tugas pimpinan, pengelola, guru, dan tenaga kependidikan MI Hubbul Wathan.</p>', 'published', '2026-06-14 17:06:36', '2026-06-13 12:03:28', '2026-06-14 17:06:36');
INSERT INTO "pages" ("id", "title", "slug", "excerpt", "body", "status", "published_at", "created_at", "updated_at") VALUES (8, 'Kurikulum', 'kurikulum', 'Arah pembelajaran dan program pendidikan MI Hubbul Wathan.', '<p>MI Hubbul Wathan menyelenggarakan pembelajaran berdasarkan ketentuan kurikulum nasional dan pendidikan madrasah yang berlaku. Program pembelajaran memadukan mata pelajaran umum, pendidikan agama, pembiasaan karakter, serta kegiatan pengembangan minat peserta didik.</p>
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "cover_image", "status", "published_at", "created_at", "updated_at") VALUES (1, 'Kegiatan Belajar Madrasah Berjalan Tertib', 'kegiatan-belajar-madrasah', 'Kegiatan belajar berlangsung dengan suasana tertib dan pendampingan guru kelas.', 'MI Hubbul Wathan terus mendorong kegiatan belajar yang terencana, ramah anak, dan sejalan dengan nilai-nilai madrasah. Guru kelas mendampingi siswa melalui kegiatan membaca, berhitung, diskusi kelompok, dan pembiasaan adab.', NULL, 'published', '2026-06-13 17:06:36', '2026-06-07 16:03:19', '2026-06-14 17:06:36');
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "cover_image", "status", "published_at", "created_at", "updated_at") VALUES (2, 'Pembiasaan Pagi Membentuk Karakter Siswa', 'pembiasaan-pagi-membentuk-karakter-siswa', 'Siswa mengikuti doa pagi, murajaah, dan arahan wali kelas sebelum pembelajaran.', 'Pembiasaan pagi menjadi bagian penting dari kehidupan madrasah. Kegiatan ini membantu siswa memulai hari dengan tertib, tenang, dan siap mengikuti pelajaran.', NULL, 'published', '2026-06-12 17:06:36', '2026-06-07 16:03:20', '2026-06-14 17:06:36');
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "cover_image", "status", "published_at", "created_at", "updated_at") VALUES (3, 'Guru Mengikuti Rapat Persiapan Kalender Akademik', 'rapat-persiapan-kalender-akademik', 'Dewan guru menyusun agenda kegiatan pembelajaran dan program sekolah.', 'Rapat persiapan kalender akademik dilakukan untuk memastikan kegiatan sekolah berjalan terencana. Agenda meliputi penilaian, kegiatan keagamaan, ekstrakurikuler, dan komunikasi dengan orang tua.', NULL, 'published', '2026-06-11 17:06:36', '2026-06-07 16:03:20', '2026-06-14 17:06:36');
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "cover_image", "status", "published_at", "created_at", "updated_at") VALUES (4, 'Kegiatan Literasi Kelas Rendah', 'kegiatan-literasi-kelas-rendah', 'Siswa kelas rendah dilatih membaca nyaring dan mengenal kosakata baru.', 'Program literasi kelas rendah dilakukan secara bertahap melalui bacaan pendek, permainan kata, dan pendampingan guru. Kegiatan ini bertujuan memperkuat dasar membaca siswa.', NULL, 'published', '2026-06-10 17:06:36', '2026-06-07 16:03:20', '2026-06-14 17:06:36');
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "body", "cover_image", "status", "published_at", "created_at", "updated_at") VALUES (5, 'Kerja Bakti Menjaga Kebersihan Lingkungan Madrasah', 'kerja-bakti-lingkungan-madrasah', 'Siswa dan guru bersama-sama menjaga lingkungan sekolah tetap bersih.', 'Kegiatan kerja bakti menjadi sarana pembiasaan tanggung jawab dan kepedulian terhadap lingkungan. Siswa diajak merapikan kelas, halaman, dan area kegiatan bersama.', NULL, 'published', '2026-06-09 17:06:36', '2026-06-07 16:03:20', '2026-06-14 17:06:36');
